USE aerosoft360_rebuild;
CREATE TABLE IF NOT EXISTS customers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,tin VARCHAR(40) NULL,phone VARCHAR(30) NULL,address VARCHAR(255) NULL,credit_days SMALLINT UNSIGNED NOT NULL DEFAULT 30,credit_limit DECIMAL(18,2) NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'active',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sales_representatives (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,manager_name VARCHAR(160) NULL,channel VARCHAR(50) NOT NULL DEFAULT 'direct_sales',default_commission_rate DECIMAL(18,2) NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'active',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS articles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,category VARCHAR(80) NOT NULL,set_name VARCHAR(80) NOT NULL DEFAULT 'Standard 10 Piece Set',pieces_per_set SMALLINT UNSIGNED NOT NULL DEFAULT 10,selling_price DECIMAL(18,2) NOT NULL DEFAULT 0,commission_rate DECIMAL(18,2) NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'active',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS article_sizes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,article_id BIGINT UNSIGNED NOT NULL,size_label VARCHAR(30) NOT NULL,pieces_per_set DECIMAL(8,2) NOT NULL DEFAULT 2,sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,UNIQUE KEY article_size_unique(article_id,size_label),FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS customer_pos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,number VARCHAR(40) NOT NULL UNIQUE,customer_id BIGINT UNSIGNED NOT NULL,sales_rep_id BIGINT UNSIGNED NOT NULL,customer_po_reference VARCHAR(80) NULL,po_date DATE NOT NULL,sale_type VARCHAR(20) NOT NULL DEFAULT 'credit',status VARCHAR(25) NOT NULL DEFAULT 'draft',total DECIMAL(18,2) NOT NULL DEFAULT 0,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(sales_rep_id) REFERENCES sales_representatives(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS customer_po_lines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_po_id BIGINT UNSIGNED NOT NULL,article_id BIGINT UNSIGNED NOT NULL,sets DECIMAL(10,2) NOT NULL,pieces DECIMAL(12,2) NOT NULL,rate DECIMAL(18,2) NOT NULL,line_total DECIMAL(18,2) NOT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(customer_po_id) REFERENCES customer_pos(id) ON DELETE CASCADE,FOREIGN KEY(article_id) REFERENCES articles(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sales_orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,number VARCHAR(40) NOT NULL UNIQUE,customer_po_id BIGINT UNSIGNED NOT NULL UNIQUE,customer_id BIGINT UNSIGNED NOT NULL,sales_rep_id BIGINT UNSIGNED NOT NULL,order_date DATE NOT NULL,status VARCHAR(25) NOT NULL DEFAULT 'confirmed',total DECIMAL(18,2) NOT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(customer_po_id) REFERENCES customer_pos(id),FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(sales_rep_id) REFERENCES sales_representatives(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sales_order_size_lines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sales_order_id BIGINT UNSIGNED NOT NULL,article_id BIGINT UNSIGNED NOT NULL,size_label VARCHAR(30) NOT NULL,quantity DECIMAL(12,2) NOT NULL,rate DECIMAL(18,2) NOT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(sales_order_id) REFERENCES sales_orders(id) ON DELETE CASCADE,FOREIGN KEY(article_id) REFERENCES articles(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sales_invoices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,number VARCHAR(40) NOT NULL UNIQUE,sales_order_id BIGINT UNSIGNED NOT NULL UNIQUE,customer_id BIGINT UNSIGNED NOT NULL,sales_rep_id BIGINT UNSIGNED NOT NULL,invoice_date DATE NOT NULL,due_date DATE NOT NULL,sale_type VARCHAR(20) NOT NULL,status VARCHAR(25) NOT NULL DEFAULT 'unpaid',subtotal DECIMAL(18,2) NOT NULL,discount DECIMAL(18,2) NOT NULL DEFAULT 0,tax DECIMAL(18,2) NOT NULL DEFAULT 0,total DECIMAL(18,2) NOT NULL,received_amount DECIMAL(18,2) NOT NULL DEFAULT 0,outstanding DECIMAL(18,2) NOT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(sales_order_id) REFERENCES sales_orders(id),FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(sales_rep_id) REFERENCES sales_representatives(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS customer_receipts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,number VARCHAR(40) NOT NULL UNIQUE,customer_id BIGINT UNSIGNED NOT NULL,sales_rep_id BIGINT UNSIGNED NOT NULL,receipt_date DATE NOT NULL,payment_method VARCHAR(30) NOT NULL,reference VARCHAR(80) NULL,amount DECIMAL(18,2) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'posted',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(sales_rep_id) REFERENCES sales_representatives(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS receipt_allocations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,receipt_id BIGINT UNSIGNED NOT NULL,invoice_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(18,2) NOT NULL,days_taken INT NOT NULL,commission_amount DECIMAL(18,2) NOT NULL DEFAULT 0,commission_status VARCHAR(25) NOT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(receipt_id) REFERENCES customer_receipts(id) ON DELETE CASCADE,FOREIGN KEY(invoice_id) REFERENCES sales_invoices(id)) ENGINE=InnoDB;
